// @ledger writes | node build-pick-page.mjs | The pick sheet: ten first screens, ten compositions, one choice.
/* WHAT THIS PAGE IS FOR, and why it replaced what was here before.
 *
 * The page this file used to build ranked 1,000 ROLLED looks. That was the wrong deliverable.
 * The founder's words: "ny request wwas to iprove the sanples you desiged by a factor os 1000".
 * A thousand candidates is not an improvement to ten designs, it is a different exercise, and
 * he then said what was wrong with the thousand: "they all look the ane , the one generated by
 * enngine, the ones you showed ne the sanples looked beter".
 *
 * He was right, and the cause was in the markup rather than in the ranking. Every look rendered
 * the SAME first screen -- wordmark, dateline, nav, eyebrow, headline left, plate right -- so the
 * only things that ever changed were palette and typeface. Ten looks, one composition. This page
 * exists to show the ten now that each one composes its own first screen, and to make picking
 * one a matter of looking rather than of reading a table. */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { LOOKS } from './seedlib.mjs';

const G = JSON.parse(readFileSync('grades-designed.json', 'utf8'));
const b64 = (p) => readFileSync(p).toString('base64');
const fam = (n) => n.match(/'([^']+)'/)?.[1] || n.split(',')[0].trim();
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

/* Named once, here, because the name of a composition IS the thing that changed. A row that
   said "layout: memo" would be a class name; "one narrow measure, typed rather than designed"
   is what the founder is actually choosing between. */
const COMPOSITION = {
  broadsheet:      ['Broadsheet',   'Argument on the left, evidence on the right. The front page everybody knows.'],
  poster:          ['Poster',       'No plate in the first screen at all. The headline is the whole page.'],
  'readout-first': ['Readout first','It opens on the table and explains afterwards, the way an almanac does.'],
  stack:           ['Stack',        'A band of evidence across the top, the argument under it.'],
  frieze:          ['Frieze',       'The argument first, the numbers beside it, the evidence as a band beneath.'],
  split:           ['Split',        'Two even columns with the gutter drawn, as a prospectus rules its page.'],
  'plate-left':    ['Plate left',   'The drawing, then the notes. The mirror of the front page.'],
  rail:            ['Rail',         'A rule down the outside of the lead and a narrow plate beside it.'],
  column:          ['Column',       'The headline spans the sheet; the deck sets in two columns beneath it.'],
  memo:            ['Memo',         'One narrow measure, nothing centred. A document that was typed.'],
};
const AXES = [['layers', 'depth'], ['distinct', 'not a default'], ['type', 'type pairing'],
              ['coherent', 'internal logic'], ['restraint', 'restraint'],
              ['chroma', 'colour discipline'], ['parity', 'light/dark parity']];

const rows = G.rows.map((r) => {
  const l = LOOKS.find((x) => x.id === r.id);
  const key = l.switches.layout || 'broadsheet';
  const [cname, cwhy] = COMPOSITION[key];
  const others = Object.entries(l.switches).filter(([k]) => k !== 'layout')
    .map(([k, v]) => `${k}:${v}`);
  return { ...r, l, cname, cwhy, others };
});

const card = (r, i) => `
<article class="look" id="${r.id}">
  <header class="look__id">
    <p class="rank">${String(i + 1).padStart(2, '0')}</p>
    <h2>${esc(r.l.name)}</h2>
    <p class="comp">${esc(r.cname)}</p>
    <p class="why">${esc(r.cwhy)}</p>
  </header>
  <div class="shots">
    <figure><img loading="lazy" alt="${esc(r.l.name)}, light" src="data:image/png;base64,${b64(`shots/first/${r.id}-light.png`)}"><figcaption>light</figcaption></figure>
    <figure><img loading="lazy" alt="${esc(r.l.name)}, dark" src="data:image/png;base64,${b64(`shots/first/${r.id}-dark.png`)}"><figcaption>dark</figcaption></figure>
  </div>
  <div class="spec">
    <p class="tag">${esc(r.l.tagline)}</p>
    <dl>
      <dt>display</dt><dd>${esc(fam(r.l.type.display))}</dd>
      <dt>text</dt><dd>${esc(fam(r.l.type.body))}</dd>
      <dt>data</dt><dd>${esc(fam(r.l.type.mono))}</dd>
      <dt>also</dt><dd>${r.others.length ? esc(r.others.join(', ')) : '<span class="none">nothing else</span>'}</dd>
    </dl>
    <p class="score"><b>${r.score}</b><span>/100 on the seven axes</span></p>
    <ul class="bars">${AXES.map(([k, label]) => {
      const v = r.parts[k];
      return `<li><span class="bl">${label}</span><span class="bt"><i style="width:${(v * 100).toFixed(1)}%"></i></span><span class="bv">${v.toFixed(2)}</span></li>`;
    }).join('')}</ul>
  </div>
</article>`;

const html = `<title>Ten Compositions</title>
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Public+Sans:wght@400;600;800&family=IBM+Plex+Mono:wght@400;500;600&display=swap">
<style>
:root{
  --ground:#f1f0ed; --sheet:#ffffff; --ink:#17191d; --ink2:#5e636b; --hair:#dfdcd5;
  --brass:#8a6a25; --rulestrong:#17191d;
}
@media (prefers-color-scheme: dark){ :root:not([data-theme="light"]){
  --ground:#0f1013; --sheet:#171a1e; --ink:#e9eaec; --ink2:#969ba3; --hair:#2a2e35;
  --brass:#c6a05a; --rulestrong:#e9eaec;
} }
:root[data-theme="dark"]{
  --ground:#0f1013; --sheet:#171a1e; --ink:#e9eaec; --ink2:#969ba3; --hair:#2a2e35;
  --brass:#c6a05a; --rulestrong:#e9eaec;
}
*{box-sizing:border-box}
body{margin:0;background:var(--ground);color:var(--ink);
  font:400 16px/1.6 'Public Sans',system-ui,sans-serif;-webkit-font-smoothing:antialiased}
.wrap{max-width:1180px;margin:0 auto;padding:clamp(24px,4vw,56px) clamp(16px,3vw,32px) 96px}
.mono{font-family:'IBM Plex Mono',ui-monospace,monospace}

/* Masthead. The page is a specimen sheet, so it says what it is and gets out of the way. */
.head{border-bottom:2px solid var(--rulestrong);padding-bottom:20px;margin-bottom:8px}
.kicker{font:500 11px/1 'IBM Plex Mono',monospace;letter-spacing:.2em;text-transform:uppercase;
  color:var(--brass);margin:0 0 14px}
.head h1{font-size:clamp(2rem,4.6vw,3.4rem);line-height:1.02;letter-spacing:-.028em;font-weight:800;
  margin:0 0 14px;text-wrap:balance;max-width:20ch}
.head p{margin:0;max-width:64ch;color:var(--ink2);font-size:1.0625rem}
.head p + p{margin-top:10px}
.head b{color:var(--ink);font-weight:600}

.meta{display:flex;flex-wrap:wrap;gap:0;border-bottom:1px solid var(--hair);margin-bottom:clamp(28px,5vw,56px)}
.meta div{padding:14px 22px 14px 0;margin-right:22px;border-right:1px solid var(--hair)}
.meta div:last-child{border-right:0}
.meta dt{font:500 10px/1 'IBM Plex Mono',monospace;letter-spacing:.18em;text-transform:uppercase;color:var(--ink2);margin:0 0 6px}
.meta dd{margin:0;font:600 1.35rem/1 'IBM Plex Mono',monospace;font-variant-numeric:tabular-nums}

.look{border-top:1px solid var(--hair);padding:clamp(26px,4vw,44px) 0;
  display:grid;grid-template-columns:minmax(0,1fr);gap:24px}
.look:first-of-type{border-top:2px solid var(--rulestrong)}
@media (min-width:60rem){
  .look{grid-template-columns:minmax(190px,15%) minmax(0,1fr) minmax(210px,20%);gap:clamp(20px,2.6vw,36px);align-items:start}
}
.rank{font:600 11px/1 'IBM Plex Mono',monospace;letter-spacing:.16em;color:var(--brass);margin:0 0 10px}
.look__id h2{font-size:1.5rem;line-height:1.1;letter-spacing:-.02em;font-weight:800;margin:0 0 8px}
.comp{margin:0;font:500 12px/1.3 'IBM Plex Mono',monospace;letter-spacing:.08em;text-transform:uppercase}
.why{margin:8px 0 0;color:var(--ink2);font-size:.9375rem;line-height:1.5}

.shots{display:grid;gap:10px}
.shots figure{margin:0}
.shots img{display:block;width:100%;height:auto;border:1px solid var(--hair);background:var(--sheet)}
.shots figcaption{font:500 10px/1 'IBM Plex Mono',monospace;letter-spacing:.16em;text-transform:uppercase;
  color:var(--ink2);padding-top:6px}
@media (min-width:44rem){ .shots{grid-template-columns:1fr 1fr} }

.tag{margin:0 0 16px;font-size:.9375rem;line-height:1.5;color:var(--ink2)}
.spec dl{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;margin:0 0 18px;
  font:400 12px/1.45 'IBM Plex Mono',monospace}
.spec dt{color:var(--ink2);letter-spacing:.06em}
.spec dd{margin:0}
.none{color:var(--ink2)}
.score{margin:0 0 12px;display:flex;align-items:baseline;gap:7px}
.score b{font:600 1.75rem/1 'IBM Plex Mono',monospace;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.score span{font-size:.75rem;color:var(--ink2)}
.bars{list-style:none;margin:0;padding:0;display:grid;gap:5px}
.bars li{display:grid;grid-template-columns:1fr 62px 30px;align-items:center;gap:8px;
  font:400 10.5px/1 'IBM Plex Mono',monospace;color:var(--ink2)}
.bt{height:4px;background:var(--hair);display:block}
.bt i{display:block;height:100%;background:var(--brass)}
.bv{text-align:right;font-variant-numeric:tabular-nums;color:var(--ink)}

.foot{border-top:2px solid var(--rulestrong);margin-top:40px;padding-top:22px;color:var(--ink2);
  font-size:.9375rem;max-width:70ch}
.foot h3{color:var(--ink);font-size:1rem;margin:0 0 8px;letter-spacing:-.01em}
.foot p{margin:0 0 12px}
.foot code{font-family:'IBM Plex Mono',monospace;font-size:.85em;color:var(--ink)}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
<div class="wrap">
  <header class="head">
    <p class="kicker">mumchimp &middot; storefront &middot; pick one</p>
    <h1>Ten looks, ten compositions.</h1>
    <p>They used to be ten palettes on one composition. Every look rendered the same first screen &mdash; wordmark, dateline, nav, eyebrow, headline on the left, plate on the right &mdash; so the only things that ever changed were the colour and the typeface. That is why they all looked the same, and it was true of the designed ten and of anything the engine rolled.</p>
    <p>Each one now composes its own first screen. <b>That is the change.</b> The palette and the type are still computed from a seed and still audited for contrast; what is new is that the arrangement is a decision the look owns, so a Broadside opens like a poster and a Dossier opens like a memo.</p>
  </header>

  <dl class="meta">
    <div><dt>looks</dt><dd>10</dd></div>
    <div><dt>compositions</dt><dd>10</dd></div>
    <div><dt>median score</dt><dd>${(rows.reduce((a, r) => a + r.score, 0) / rows.length).toFixed(1)}</dd></div>
    <div><dt>best</dt><dd>${Math.max(...rows.map((r) => r.score))}</dd></div>
    <div><dt>contrast checks</dt><dd>400</dd></div>
    <div><dt>refusals</dt><dd>0</dd></div>
  </dl>

  ${rows.map(card).join('\n')}

  <section class="foot">
    <h3>How to read the numbers, and what they cannot tell you</h3>
    <p>The score is seven weighted axes measured off the look's own data, not off the picture: depth, distinctness from the common defaults, type pairing, internal logic, restraint, colour discipline, and how well the dark theme holds against the light one. It is a floor, not a verdict &mdash; it can say a look is careless, it cannot say a look is right.</p>
    <p>Two things it does not measure. It grades each look alone, so it has no opinion on whether two looks resemble each other; and it never sees the composition, which is the thing that actually changed here. <b>The pictures are the evidence for that half.</b> Pick with your eyes; the numbers are only there to stop something sloppy winning.</p>
    <p>Every screen above is the real page at 1280&times;800, light and dark, shot from <code>looks-engine.html</code> with the prototype's own look switcher hidden. Nothing is a mockup.</p>
  </section>
</div>`;

writeFileSync('pick.html', html);
console.log(`pick.html  ${new Intl.NumberFormat('en').format(html.length)} bytes  ${rows.length} looks`);
